bool mdit_is_punct(uint32_t cp)
{
    if (cp >= 0x110000u) return false;
    uint16_t page = k_punct_index[cp >> 8];
    return ((k_punct_pages[page][(cp & 0xFFu) >> 3] >> (cp & 7u)) & 1u) != 0u;
}
